import sys

def build_sparse_table(arr):
    n = len(arr)
    max_level = n.bit_length()
    st = [[0] * n for _ in range(max_level)]
    for i in range(n):
        st[0][i] = arr[i]
    j = 1
    while (1 << j) <= n:
        step = 1 << (j - 1)
        for i in range(n - (1 << j) + 1):
            st[j][i] = st[j-1][i] | st[j-1][i + step]
        j += 1
    return st

def precompute_log(n):
    log_table = [0] * (n + 1)
    for i in range(2, n + 1):
        log_table[i] = log_table[i // 2] + 1
    return log_table

def query_or(st, log_table, l, r):
    length = r - l + 1
    k = log_table[length]
    return st[k][l] | st[k][r - (1 << k) + 1]

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        n = int(next(it))
        k = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        double_a = a + a
        st = build_sparse_table(double_a)
        log_table = precompute_log(2 * n)
        max_rounds = 0
        for i in range(n):
            lo, hi = 1, n
            best_len = n
            while lo <= hi:
                mid = (lo + hi) // 2
                cur_or = query_or(st, log_table, i, i + mid - 1)
                if cur_or >= k:
                    best_len = mid
                    hi = mid - 1
                else:
                    lo = mid + 1
            rounds = best_len - 1
            if rounds > max_rounds:
                max_rounds = rounds
        out_lines.append(str(max_rounds))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
